    current_sequence = sequence[:]

    while True:
        next_sequence = []
        for i in range(n):
            if i % 2 == 0:
                next_sequence.append((current_sequence[i] + 1) % n)
            else:
                next_sequence.append((current_sequence[i] - 1) % n)

        if next_sequence == target_sequence:
            return "Yes"

        if next_sequence == current_sequence:
            return "No"

        current_sequence = next_sequence

